#include <nlohmann/json.hpp>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <set>
#include <string_view>
using json=nlohmann::json;using namespace Slic3r;
constexpr size_t MAX_ARCHIVE=128*1024*1024,MAX_EXPANDED=256*1024*1024,MAX_OUTPUT=150*1024*1024,MAX_TRIANGLES=2000000;
struct EntryCheck{size_t expected=0,actual=0;bool xml=false;std::string suffix;};
size_t check_entry(void* opaque,mz_uint64 offset,const void* data,size_t length){auto& check=*static_cast<EntryCheck*>(opaque);if(offset!=check.actual||length>check.expected-check.actual)return 0;check.actual+=length;if(check.xml){if(std::string_view(static_cast<const char*>(data),length).find('\0')!=std::string_view::npos)return 0;std::string chunk=check.suffix+std::string(static_cast<const char*>(data),length);for(char&c:chunk)c=static_cast<char>(std::toupper(static_cast<unsigned char>(c)));if(chunk.find("<!DOCTYPE")!=std::string::npos||chunk.find("<!ENTITY")!=std::string::npos)return 0;check.suffix=chunk.substr(chunk.size()>16?chunk.size()-16:0);}return length;}
json inspect_archive(const std::string& filename){if(std::filesystem::file_size(filename)>MAX_ARCHIVE)throw std::runtime_error("3MF archive exceeds128MB");mz_zip_archive zip{};if(!mz_zip_reader_init_file(&zip,filename.c_str(),0))throw std::runtime_error("Invalid3MF ZIP");json ignored=json::array();try{const size_t count=mz_zip_reader_get_num_files(&zip);if(count>4096)throw std::runtime_error("3MF entry limit exceeded");size_t expanded=0;std::set<std::string> names;for(mz_uint i=0;i<count;++i){mz_zip_archive_file_stat stat{};if(!mz_zip_reader_file_stat(&zip,i,&stat))throw std::runtime_error("Invalid3MF ZIP directory");std::string name=stat.m_filename;if(name.empty()||name.front()=='/'||name.find("..")!=std::string::npos||name.find('\\')!=std::string::npos||!names.insert(name).second||stat.m_is_encrypted)throw std::runtime_error("Unsafe3MF entry");if(stat.m_uncomp_size>MAX_EXPANDED-expanded)throw std::runtime_error("3MF expanded limit exceeded");expanded+=stat.m_uncomp_size;EntryCheck check{static_cast<size_t>(stat.m_uncomp_size),0,name.find(".model")!=std::string::npos||name.find(".xml")!=std::string::npos||name.find(".config")!=std::string::npos,{}};if(!mz_zip_reader_extract_to_callback(&zip,i,check_entry,&check,0)||check.actual!=check.expected)throw std::runtime_error("3MF bounded extraction or XML entity check failed");if(name.rfind("Metadata/",0)==0&&name!="Metadata/Slic3r_PE_model.config")ignored.push_back(name);}mz_zip_reader_end(&zip);return ignored;}catch(...){mz_zip_reader_end(&zip);throw;}}
json matrix(const Transform3d& t){json out=json::array();for(int col=0;col<4;++col)for(int row=0;row<3;++row){double value=t.matrix()(row,col);if(!std::isfinite(value))throw std::runtime_error("Nonfinite native transform");out.push_back(value);}return out;}
json settings(const ConfigBase& config){json result=json::object();for(const auto& key:config.keys()){const ConfigOption* option=config.option(key);const auto value=option->serialize();if(key=="post_process"&&!value.empty())throw std::runtime_error("Native post_process commands are prohibited");result[key]=value;}return result;}
json paint(const FacetsAnnotation& facets,size_t triangleCount){json result=json::object();if(!facets.empty())for(size_t i=0;i<triangleCount;++i){const std::string value=facets.get_triangle_as_string(static_cast<int>(i));if(!value.empty())result[std::to_string(i)]=value;}return result;}
json dump_model(const Model& model,const DynamicPrintConfig& config,const ConfigSubstitutionContext& substitutions){json out={{"format","orca-native-prusa-import"},{"version",1},{"sourceRevision","8500fcdccaa10b5099ac20d252af3a7c560046f1"},{"settings",settings(config)},{"objects",json::array()},{"unrecognizedKeys",substitutions.unrecogized_keys}};size_t triangles=0,instances=0;int requiredFilaments=1;if(model.objects.size()>10000)throw std::runtime_error("Native object limit exceeded");for(const auto* object:model.objects){if(object->config.option("extruder"))requiredFilaments=std::max(requiredFilaments,object->config.extruder());json item={{"name",object->name},{"printable",object->printable},{"settings",settings(object->config.get())},{"instances",json::array()},{"volumes",json::array()},{"layerHeightProfile",object->layer_height_profile.get()},{"layerConfigRanges",json::array()}};for(const auto& range:object->layer_config_ranges)item["layerConfigRanges"].push_back({{"minZ",range.first.first},{"maxZ",range.first.second},{"settings",settings(range.second.get())}});for(const auto* instance:object->instances){if(++instances>10000)throw std::runtime_error("Native instance limit exceeded");item["instances"].push_back({{"matrix",matrix(instance->get_matrix())},{"printable",instance->printable}});}for(const auto* volume:object->volumes){if(volume->config.option("extruder"))requiredFilaments=std::max(requiredFilaments,volume->config.extruder());for(int slot:volume->get_extruders())requiredFilaments=std::max(requiredFilaments,slot);const auto& mesh=volume->mesh().its;triangles+=mesh.indices.size();if(triangles>MAX_TRIANGLES)throw std::runtime_error("Native triangle limit exceeded");json positions=json::array();for(const auto& face:mesh.indices)for(int vertex:face){if(vertex<0||static_cast<size_t>(vertex)>=mesh.vertices.size())throw std::runtime_error("Invalid native triangle index");for(float value:mesh.vertices[vertex]){if(!std::isfinite(value)||std::abs(value)>1e7)throw std::runtime_error("Invalid native vertex");positions.push_back(value);}}json painting={{"version",1}};for(auto&& entry:std::vector<std::pair<std::string,const FacetsAnnotation*>>{{"supports",&volume->supported_facets},{"seam",&volume->seam_facets},{"color",&volume->mmu_segmentation_facets},{"fuzzy",&volume->fuzzy_skin_facets}}){auto value=paint(*entry.second,mesh.indices.size());if(!value.empty())painting[entry.first]=std::move(value);}item["volumes"].push_back({{"name",volume->name},{"type",ModelVolume::type_to_string(volume->type())},{"settings",settings(volume->config.get())},{"matrix",matrix(volume->get_matrix())},{"positions",std::move(positions)},{"painting",std::move(painting)},{"source",{{"file",volume->source.input_file},{"objectIndex",volume->source.object_idx},{"volumeIndex",volume->source.volume_idx},{"matrix",matrix(volume->source.transform.get_matrix())},{"offset",{volume->source.mesh_offset.x(),volume->source.mesh_offset.y(),volume->source.mesh_offset.z()}},{"inches",volume->source.is_converted_from_inches},{"meters",volume->source.is_converted_from_meters}}}});}out["objects"].push_back(std::move(item));}if(requiredFilaments>64)throw std::runtime_error("Native material slot limit exceeded");out["requiredFilamentCount"]=requiredFilaments;out["triangleCount"]=triangles;return out;}
int main(int argc,char** argv){try{if(argc==2&&std::string(argv[1])=="--version"){std::cout<<"OrcaPrusaImporter-2.4.2 revision8500fcdccaa10b5099ac20d252af3a7c560046f1\n";return 0;}if(argc!=3)throw std::runtime_error("Expected input3MF and outputJSON paths");const auto ignored=inspect_archive(argv[1]);PrusaFileParser detector;if(!detector.check_3mf_from_prusa(argv[1]))throw std::runtime_error("Archive does not identify as PrusaSlicer3MF");Model model;DynamicPrintConfig config;ConfigSubstitutionContext substitutions(ForwardCompatibilitySubstitutionRule::Enable);if(!load_3mf(argv[1],config,substitutions,&model,true))throw std::runtime_error("Native Prusa import failed");auto out=dump_model(model,config,substitutions);out["carriersNotInterpretedByNative"]=ignored;const auto text=out.dump();if(text.size()>MAX_OUTPUT)throw std::runtime_error("Native normalized data exceeds150MB");std::ofstream stream(argv[2],std::ios::binary|std::ios::trunc);if(!stream||!(stream<<text))throw std::runtime_error("Could not save native imported model");return 0;}catch(const std::exception& error){std::cerr<<error.what()<<"\n";return 1;}}
